const messages = $input.first().json.messages || [];

// Outlook Calendar bot messages have subtype='bot_message' or a bot_id
const botMsgs = messages.filter(m => m.bot_id || m.subtype === 'bot_message');
if (botMsgs.length === 0) return []; // no bot posts today — stop

// Parse all lines matching: 'Name off  (email@domain.com)'
const pattern = /^(.+?)\s+off\s*\(([^)]+@[^)]+)\)/gm;
const absences = [];

for (const msg of botMsgs) {
  const text = (msg.text || '').trim();
  let match;
  pattern.lastIndex = 0;
  while ((match = pattern.exec(text)) !== null) {
    const name  = match[1].trim();
    const email = match[2].trim();
    if (!absences.find(a => a.email === email)) {
      absences.push({ name, email });
    }
  }
}

if (absences.length === 0) return []; // nobody off today — stop

return [{ json: { absences } }];

// ── Toggle this flag ─────────────────────────────────────────
const TEST_MODE = true;  // true = only Team Member 1 gets emails; false = everyone
// ─────────────────────────────────────────────────────────────

const everyone = [
  { name: 'Team Member 1', email: 'member1@example.com' },
  { name: 'Team Member 2',       email: 'member2@example.com' },
  { name: 'Team Member 3',      email: 'member3@example.com' },
  { name: 'Team Member 4',         email: 'member4@example.com' }
];

const team = TEST_MODE
  ? [{ name: 'Team Member 1', email: 'member1@example.com' }]
  : everyone;

const absences = $('Parse Absences').first().json.absences;
return [{ json: { team, absences } }];

const { team, absences } = $input.first().json;

// Persistent dedup store — prevents duplicate emails if run more than once
const store = $getWorkflowStaticData('global');
if (!store.sent) store.sent = {};

// Prune entries older than 48 hours
const cutoff = Date.now() - 48 * 3600 * 1000;
for (const k of Object.keys(store.sent)) {
  if (store.sent[k] < cutoff) delete store.sent[k];
}

const now = new Date();
const days   = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const months = ['January','February','March','April','May','June',
                 'July','August','September','October','November','December'];
const todayLabel = `${days[now.getDay()]}, ${months[now.getMonth()]} ${now.getDate()}`;
const todayKey   = now.toISOString().slice(0, 10);

const items = [];
for (const absence of absences) {
  const dedupKey = `${absence.email}::${todayKey}`;
  if (store.sent[dedupKey]) continue; // already emailed today for this person
  items.push({ json: { absence, team, todayLabel, dedupKey } });
}

// Returning multiple items = one email per absent person
return items;

const { absence, team, todayLabel, dedupKey } = $input.first().json;

const subject = `[Core Facility] ${absence.name} is out today — ${todayLabel}`;

const html = [
  '<p style="font-family:sans-serif;margin:0 0 12px">Hi team,</p>',
  '<p style="font-family:sans-serif;margin:0 0 12px">',
  `This is a reminder that <strong>${absence.name}</strong> is `,
  `<strong>out of office today, ${todayLabel}</strong>.`,
  '</p>',
  '<p style="font-family:sans-serif;margin:0 0 12px;color:#555">',
  'Please plan accordingly and reach out to other team members if you need assistance.',
  '</p>',
  '<hr style="border:none;border-top:1px solid #e0e0e0;margin:20px 0">',
  '<p style="font-family:sans-serif;color:#aaa;font-size:0.8em;margin:0">',
  'Core Facility Calendar &bull; Automated notification via n8n',
  '</p>'
].join('');

// Send to all team members as a comma-separated list
const toList = team.map(m => m.email).join(',');

return [{ json: { subject, html, toList, dedupKey } }];

